import{seeded as x,ridgeAt as g}from"./city.min.js";import{sunTimes as d,dayOfYear as I}from"./daylight.min.js";const M=Math.PI/180,m=3600*1e3;export const LATITUDE=40,POLE=[Math.cos(LATITUDE*M),Math.sin(LATITUDE*M),0],SUNSET_FRAME={swing:.2,turn:8.5};export function turnNorth([o,t,r],s){const n=s*M;return[o*Math.cos(n)-r*Math.sin(n),t,r*Math.cos(n)+o*Math.sin(n)]}export const SYNODIC_DAYS=29.530588853,NEW_MOON=Date.UTC(2e3,0,6,18,14);const P=861640905e-1;export function declination(o){return 23.44*M*Math.cos(2*Math.PI*(I(o)-172)/365)}export function direction(o,t,r=LATITUDE){const s=r*M,n=-Math.cos(t)*Math.sin(o),c=Math.cos(s)*Math.sin(t)-Math.sin(s)*Math.cos(t)*Math.cos(o),a=Math.sin(s)*Math.sin(t)+Math.cos(s)*Math.cos(t)*Math.cos(o);return[c,a,n]}function S(o){return o.getHours()+o.getMinutes()/60+o.getSeconds()/3600+o.getMilliseconds()/m}export function moonAge(o){return((o.getTime()-NEW_MOON)/(24*m)/SYNODIC_DAYS%1+1)%1}const D=(o,t)=>Math.acos(Math.min(1,Math.max(-1,o[0]*t[0]+o[1]*t[1]+o[2]*t[2])));export function skyAt(o){const{sunrise:t,sunset:r}=d(o),s=(t+r)/2,n=(r-t)/2,c=declination(o),a=LATITUDE*M,e=c*SUNSET_FRAME.swing,h=Math.acos(Math.min(1,Math.max(-1,-Math.tan(a)*Math.tan(e)))),i=S(o),u=turnNorth(direction((i-s)/n*h,e),SUNSET_FRAME.turn),f=moonAge(o),p=direction((i-s)/12*Math.PI-2*Math.PI*f,c*Math.cos(2*Math.PI*f)),l=(o.getTime()/P%1+1)%1*2*Math.PI;return{sun:u,moon:p,age:f,turn:l,sunHeight:Math.asin(u[1]),moonHeight:Math.asin(p[1]),elongation:D(u,p)}}export function bearingOf([o,,t]){return Math.atan2(o,-t)/M}const y=.9;export function sunClear(o,t=g){const r=Math.max(0,t(bearingOf(o.sun))),s=o.sunHeight/M-r;return Math.min(1,Math.max(0,s/y+.5))}export function lightFrom(o){const t=Math.sin(4*M);let r=[.3,1,.2];o.sunHeight>-6*M?r=o.sun:o.moonHeight>0&&(r=o.moon);let[s,n,c]=r;if(n<t){const e=Math.hypot(s,c)||1,h=Math.sqrt(1-t*t)/e;s*=h,c*=h,n=t}const a=Math.hypot(s,n,c);return[s/a,n/a,c/a]}export function discBasis(o,t){const r=(e,h)=>e[0]*h[0]+e[1]*h[1]+e[2]*h[2],s=e=>{const h=r(e,o),i=e.map((f,p)=>f-h*o[p]),u=Math.hypot(...i);return u>1e-6?i.map(f=>f/u):null},n=s(t)||s([0,1,0])||s([1,0,0]),c=o.map(e=>-e),a=[c[1]*n[2]-c[2]*n[1],c[2]*n[0]-c[0]*n[2],c[0]*n[1]-c[1]*n[0]];return{right:n,up:a,normal:c}}export function starField(o=420,t=20260926){const r=x(t),s=[];for(let n=0;n<o;n++){const c=r()*2-1,a=r()*Math.PI*2,e=Math.sqrt(1-c*c);s.push([e*Math.cos(a),c,e*Math.sin(a),.35+.65*r()**3])}return s}export function dayLapse(o,{seconds:t=30,stepped:r=!1}={}){let s=0;return{step(n){s=Math.min(t,s+Math.max(0,n));const c=s/t*24,a=r&&s<t?Math.floor(c):c;return{at:o+a*m,done:s>=t}}}}export const CLOUDS={altitude:4800,span:411e3,tile:24e3,size:1024,cells:22,seed:20260925};export function cloudPuffs(o=CLOUDS){const t=x(o.seed),r=[];for(let s=0;s<o.cells;s++){const n=t(),c=t(),a=.03+t()*.05,e=10+Math.floor(t()*16);for(let h=0;h<e;h++){const i=t()*Math.PI*2,u=Math.sqrt(t()),f=n+Math.cos(i)*u*a*1.8,p=c+Math.sin(i)*u*a,l=a*(.35+t()*.4)*(1-u*.4);r.push([(f%1+1)%1,(p%1+1)%1,l,.55+t()*.35])}}return r}export function wrappedPuffs(o){const t=[];for(const[r,s,n,c]of o)for(const a of[-1,0,1])for(const e of[-1,0,1]){const h=r+a,i=s+e;h+n<0||h-n>1||i+n<0||i-n>1||t.push([h,i,n,c])}return t}export function cloudCover(o,t=64){const r=wrappedPuffs(o);let s=0;for(let n=0;n<t;n++)for(let c=0;c<t;c++){const a=(c+.5)/t,e=(n+.5)/t;r.some(([h,i,u])=>Math.hypot(a-h,e-i)<u)&&s++}return s/(t*t)}
